#!/usr/bin/env node
// Converts a deck generated by THIS skill (build_kickoff_pptx.js) to PDF without PowerPoint or LibreOffice: every slide is drawn as an
// SVG (shapes, custom geometry, connectors with arrows, pictures, tables, text with the Poppins fonts) inside one HTML page, and
// Chrome / Edge headless prints it. It understands the subset of DrawingML the builder writes; it is not a general PPTX renderer.
// Also the visual QA of the deck: open the PDF (or pass --png <dir> to get one PNG per slide).
//
// Usage: node pptx_a_pdf.js deck.pptx [out.pdf] [--html out.html] [--png dir]
const fs = require('fs');
const path = require('path');
const os = require('os');
const { spawnSync } = require('child_process');
const JSZip = require('jszip');

const argv = process.argv.slice(2);
const opt = (k) => { const i = argv.indexOf(k); return i >= 0 ? argv[i + 1] : null; };
const pos = argv.filter((a, i) => !a.startsWith('--') && !['--html', '--png'].includes(argv[i - 1]));
const [inFile, outPdf0] = pos;
if (!inFile) { console.error('Usage: node pptx_a_pdf.js deck.pptx [out.pdf] [--html out.html] [--png dir]'); process.exit(2); }
const outPdf = outPdf0 || inFile.replace(/\.pptx$/i, '.pdf');
const EMU = 12700; // per point
const pt = (v) => Number(v || 0) / EMU;
const unesc = (s) => String(s).replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&apos;/g, "'").replace(/&amp;/g, '&');
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const attr = (tag, name) => { const m = new RegExp(`\\b${name}="([^"]*)"`).exec(tag || ''); return m ? m[1] : null; };
const first = (xml, re) => { const m = re.exec(xml || ''); return m ? m[0] : null; };
const FONTS = path.join(__dirname, '..', 'assets', 'fonts');
const WEIGHT = { 'Poppins': 400, 'Poppins Light': 300, 'Poppins Medium': 500, 'Poppins SemiBold': 600, 'Poppins Bold': 700 };

function xfrm(xml) {
  const off = first(xml, /<a:off [^>]*\/>/), ext = first(xml, /<a:ext [^>]*\/>/), x = first(xml, /<a:xfrm[^>]*>/) || '';
  return { x: pt(attr(off, 'x')), y: pt(attr(off, 'y')), w: pt(attr(ext, 'cx')), h: pt(attr(ext, 'cy')), flipH: attr(x, 'flipH') === '1', flipV: attr(x, 'flipV') === '1' };
}
const fillOf = (spPr) => { const noLn = (spPr || '').replace(/<a:ln[\s>][\s\S]*?<\/a:ln>/g, '').replace(/<a:effectLst>[\s\S]*?<\/a:effectLst>/g, ''); if (/<a:noFill\/>/.test(noLn) && !/<a:solidFill>/.test(noLn)) return 'none'; const m = /<a:solidFill><a:srgbClr val="([0-9A-Fa-f]{6})"/.exec(noLn); return m ? '#' + m[1] : 'none'; };
const lineOf = (spPr) => { const ln = first(spPr, /<a:ln[\s>][\s\S]*?<\/a:ln>|<a:ln [^>]*\/>/); if (!ln || /<a:noFill\/>/.test(ln)) return null; const c = /<a:srgbClr val="([0-9A-Fa-f]{6})"/.exec(ln); return { color: c ? '#' + c[1] : '#000', w: pt(attr(ln, 'w') || 9525), dash: /<a:prstDash/.test(ln), tail: /<a:tailEnd type="(triangle|arrow|stealth)"/.test(ln) }; };
const shadowOf = (spPr) => /<a:outerShdw/.test(spPr || '');

// text body -> HTML (paragraphs, runs, bullets), positioned by the caller
function textHtml(tx, box) {
  const body = first(tx, /<a:bodyPr[^>]*>/) || '';
  const ins = (k, d) => (attr(body, k) != null ? pt(attr(body, k)) : d);
  const L = ins('lIns', 7.2), T = ins('tIns', 3.6), R = ins('rIns', 7.2), B = ins('bIns', 3.6);
  const anchor = { t: 'flex-start', ctr: 'center', b: 'flex-end' }[attr(body, 'anchor') || 't'];
  const paras = (tx.match(/<a:p>[\s\S]*?<\/a:p>/g) || []).map((p) => {
    const pPr = first(p, /<a:pPr[^>]*?(\/>|>[\s\S]*?<\/a:pPr>)/) || '';
    const al = { l: 'left', ctr: 'center', r: 'right', just: 'justify' }[attr(pPr, 'algn') || 'l'];
    const lnPct = /<a:lnSpc><a:spcPct val="(\d+)"/.exec(pPr), aft = /<a:spcAft><a:spcPts val="(\d+)"/.exec(pPr), bef = /<a:spcBef><a:spcPts val="(\d+)"/.exec(pPr);
    const marL = attr(pPr, 'marL') ? pt(attr(pPr, 'marL')) : 0, ind = attr(pPr, 'indent') ? pt(attr(pPr, 'indent')) : 0;
    const bu = /<a:buChar char="([^"]*)"/.exec(pPr), buClr = /<a:buClr><a:srgbClr val="([0-9A-Fa-f]{6})"/.exec(pPr), buSz = /<a:buSzPct val="(\d+)"/.exec(pPr);
    let maxSz = 0;
    const runs = (p.match(/<a:r>[\s\S]*?<\/a:r>|<a:br>[\s\S]*?<\/a:br>|<a:br\/>/g) || []).map((r) => {
      if (/^<a:br/.test(r)) return '<br/>';
      const rp = first(r, /<a:rPr[^>]*?(\/>|>[\s\S]*?<\/a:rPr>)/) || '';
      const sz = attr(rp, 'sz') ? Number(attr(rp, 'sz')) / 100 : 18; maxSz = Math.max(maxSz, sz);
      const col = /<a:solidFill><a:srgbClr val="([0-9A-Fa-f]{6})"/.exec(rp), face = /<a:latin typeface="([^"]*)"/.exec(rp);
      const fam = face ? face[1] : 'Poppins', wgt = attr(rp, 'b') === '1' ? 700 : (WEIGHT[fam] || 400), spc = attr(rp, 'spc') ? Number(attr(rp, 'spc')) / 100 : 0;
      const t = unesc(((/<a:t>([\s\S]*?)<\/a:t>/.exec(r) || [])[1]) || '');
      return `<span style="font-size:${sz}px;font-weight:${wgt};color:${col ? '#' + col[1] : '#000'};letter-spacing:${spc}px">${esc(t)}</span>`;
    }).join('');
    const endSz = /<a:endParaRPr[^>]*sz="(\d+)"/.exec(p); if (!maxSz) maxSz = endSz ? Number(endSz[1]) / 100 : 12;
    const lh = (lnPct ? Number(lnPct[1]) / 100000 : 1) * 1.5;
    const bullet = bu ? `<span style="position:absolute;left:${-(-ind)}px;transform:translateX(-100%);margin-left:${0}px;color:${buClr ? '#' + buClr[1] : 'inherit'};font-size:${maxSz * (buSz ? Number(buSz[1]) / 100000 : 1)}px;line-height:${maxSz * lh}px">${esc(unesc(bu[1]))}</span>` : '';
    const padL = marL;
    return `<div style="position:relative;text-align:${al};line-height:${lh};padding-left:${padL}px;margin:${bef ? Number(bef[1]) / 100 : 0}px 0 ${aft ? Number(aft[1]) / 100 : 0}px 0;font-size:${maxSz}px;min-height:${maxSz * lh}px">${bu ? `<span style="position:absolute;left:${marL + ind}px;color:${buClr ? '#' + buClr[1] : 'inherit'};font-size:${maxSz * (buSz ? Number(buSz[1]) / 100000 : 1)}px;line-height:${maxSz * lh}px">${esc(unesc(bu[1]))}</span>` : ''}${runs || '&#8203;'}</div>`;
  }).join('');
  return `<foreignObject x="${box.x}" y="${box.y}" width="${Math.max(1, box.w)}" height="${Math.max(1, box.h)}"><div xmlns="http://www.w3.org/1999/xhtml" style="box-sizing:border-box;width:${box.w}px;height:${box.h}px;padding:${T}px ${R}px ${B}px ${L}px;display:flex;flex-direction:column;justify-content:${anchor};font-family:Poppins;overflow:visible;word-wrap:break-word">${paras}</div></foreignObject>`;
}

function geomPath(spPr, b) {
  const prst = attr(first(spPr, /<a:prstGeom [^>]*>/), 'prst');
  if (prst === 'ellipse') return `<ellipse cx="${b.x + b.w / 2}" cy="${b.y + b.h / 2}" rx="${b.w / 2}" ry="${b.h / 2}"`;
  if (prst === 'diamond') return `<polygon points="${b.x + b.w / 2},${b.y} ${b.x + b.w},${b.y + b.h / 2} ${b.x + b.w / 2},${b.y + b.h} ${b.x},${b.y + b.h / 2}"`;
  if (prst === 'roundRect') { const g = /<a:gd name="adj" fmla="val (\d+)"/.exec(spPr); const r = Math.min(b.w, b.h) * (g ? Number(g[1]) : 16667) / 100000; return `<rect x="${b.x}" y="${b.y}" width="${b.w}" height="${b.h}" rx="${r}"`; }
  if (/<a:custGeom>/.test(spPr)) {
    const p = first(spPr, /<a:path [^>]*>[\s\S]*?<\/a:path>/) || '', pw = Number(attr(p, 'w')) || 1, ph = Number(attr(p, 'h')) || 1;
    const sx = b.w / pw, sy = b.h / ph;
    let d = '';
    (p.match(/<a:(moveTo|lnTo|close)[^>]*?(\/>|>[\s\S]*?<\/a:\1>)/g) || []).forEach((c) => {
      if (/^<a:close/.test(c)) { d += 'Z'; return; }
      const q = /<a:pt x="(-?\d+)" y="(-?\d+)"/.exec(c);
      d += `${/^<a:moveTo/.test(c) ? 'M' : 'L'}${b.x + Number(q[1]) * sx},${b.y + Number(q[2]) * sy} `;
    });
    return `<path d="${d}"`;
  }
  return `<rect x="${b.x}" y="${b.y}" width="${b.w}" height="${b.h}"`;
}

async function main() {
  const z = await JSZip.loadAsync(fs.readFileSync(inFile));
  const pres = await z.file('ppt/presentation.xml').async('string');
  const sz = first(pres, /<p:sldSz [^>]*\/>/), SW = pt(attr(sz, 'cx')), SH = pt(attr(sz, 'cy'));
  const rels = await z.file('ppt/_rels/presentation.xml.rels').async('string');
  const ids = (pres.match(/<p:sldId [^>]*\/>/g) || []).map((t) => attr(t, 'r:id'));
  const target = (rid) => { const m = new RegExp(`Id="${rid}"[^>]*Target="([^"]*)"`).exec(rels) || new RegExp(`Target="([^"]*)"[^>]*Id="${rid}"`).exec(rels); return m && m[1]; };
  const media = new Map();
  const dataUri = async (p) => { if (media.has(p)) return media.get(p); const f = z.file(p); if (!f) return ''; const b = await f.async('base64'); const u = `data:${/\.jpe?g$/i.test(p) ? 'image/jpeg' : 'image/png'};base64,${b}`; media.set(p, u); return u; };
  const svgs = [];
  for (const rid of ids) {
    const sp = 'ppt/' + target(rid).replace(/^\.?\//, '');
    const xml = await z.file(sp).async('string');
    const srels = await z.file(sp.replace('slides/', 'slides/_rels/') + '.rels').async('string');
    const relT = (r) => { const m = new RegExp(`Id="${r}"[^>]*Target="([^"]*)"`).exec(srels); return m ? path.posix.normalize(path.posix.join(path.posix.dirname(sp), m[1])) : null; };
    const bg = /<p:bg>[\s\S]*?<a:srgbClr val="([0-9A-Fa-f]{6})"/.exec(xml);
    let out = `<rect x="0" y="0" width="${SW}" height="${SH}" fill="${bg ? '#' + bg[1] : '#FFFFFF'}"/>`;
    const tree = xml.slice(xml.indexOf('<p:spTree>'));
    const els = tree.match(/<p:sp>[\s\S]*?<\/p:sp>|<p:cxnSp>[\s\S]*?<\/p:cxnSp>|<p:pic>[\s\S]*?<\/p:pic>|<p:graphicFrame>[\s\S]*?<\/p:graphicFrame>/g) || [];
    for (const el of els) {
      if (el.startsWith('<p:sp>')) {
        const spPr = first(el, /<p:spPr>[\s\S]*?<\/p:spPr>|<p:spPr\/>/) || '', b = xfrm(spPr), fill = fillOf(spPr), ln = lineOf(spPr);
        if (fill !== 'none' || ln) out += `${geomPath(spPr, b)} fill="${fill}" stroke="${ln ? ln.color : 'none'}" stroke-width="${ln ? ln.w : 0}"${ln && ln.dash ? ' stroke-dasharray="4 3"' : ''}${shadowOf(spPr) ? ' filter="url(#sh)"' : ''}/>`;
        const tx = first(el, /<p:txBody>[\s\S]*?<\/p:txBody>/);
        if (tx && /<a:t>/.test(tx)) out += textHtml(tx, b);
      } else if (el.startsWith('<p:cxnSp>')) {
        const spPr = first(el, /<p:spPr>[\s\S]*?<\/p:spPr>/) || '', b = xfrm(spPr), ln = lineOf(spPr) || { color: '#000', w: 1 };
        const x1 = b.flipH ? b.x + b.w : b.x, y1 = b.flipV ? b.y + b.h : b.y, x2 = b.flipH ? b.x : b.x + b.w, y2 = b.flipV ? b.y : b.y + b.h;
        const mid = 'm' + ln.color.slice(1);
        out += `<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${ln.color}" stroke-width="${ln.w}"${ln.dash ? ' stroke-dasharray="4 3"' : ''}${ln.tail ? ` marker-end="url(#${mid})"` : ''}/>`;
        if (ln.tail && !svgs.markers) svgs.markers = new Set();
        if (ln.tail) (svgs.markers = svgs.markers || new Set()).add(ln.color);
      } else if (el.startsWith('<p:pic>')) {
        const b = xfrm(first(el, /<p:spPr>[\s\S]*?<\/p:spPr>/)), rid2 = attr(first(el, /<a:blip [^>]*>/), 'r:embed'), p = relT(rid2);
        const src = /<a:srcRect([^>]*)\/>/.exec(el);
        const href = p ? await dataUri(p) : '';
        if (src) {
          const g = (k) => Number(attr(src[0], k) || 0) / 100000, l = g('l'), t = g('t'), r = g('r'), bb = g('b');
          out += `<svg x="${b.x}" y="${b.y}" width="${b.w}" height="${b.h}" viewBox="${l * 1000} ${t * 1000} ${(1 - l - r) * 1000} ${(1 - t - bb) * 1000}" preserveAspectRatio="none"><image href="${href}" width="1000" height="1000" preserveAspectRatio="none"/></svg>`;
        } else out += `<image href="${href}" x="${b.x}" y="${b.y}" width="${b.w}" height="${b.h}" preserveAspectRatio="none"/>`;
      } else if (el.startsWith('<p:graphicFrame>')) {
        const b = xfrm(first(el, /<p:xfrm>[\s\S]*?<\/p:xfrm>/));
        const cols = (el.match(/<a:gridCol w="(\d+)"/g) || []).map((g) => pt(/w="(\d+)"/.exec(g)[1]));
        let y = b.y;
        (el.match(/<a:tr [^>]*>[\s\S]*?<\/a:tr>/g) || []).forEach((tr) => {
          const h = pt(attr(tr, 'h'));
          let x = b.x;
          (tr.match(/<a:tc>[\s\S]*?<\/a:tc>/g) || []).forEach((tc, ci) => {
            const w = cols[ci] || 0, tcPr = first(tc, /<a:tcPr[\s\S]*?<\/a:tcPr>|<a:tcPr[^>]*\/>/) || '';
            const cf = /<\/a:lnB>\s*<a:solidFill><a:srgbClr val="([0-9A-Fa-f]{6})"/.exec(tcPr) || /<a:tcPr[^>]*>(?:(?!<a:ln)[\s\S])*?<a:solidFill><a:srgbClr val="([0-9A-Fa-f]{6})"/.exec(tcPr);
            const bc = /<a:lnB[^>]*><a:solidFill><a:srgbClr val="([0-9A-Fa-f]{6})"/.exec(tcPr);
            out += `<rect x="${x}" y="${y}" width="${w}" height="${h}" fill="${cf ? '#' + cf[1] : 'none'}" stroke="${bc ? '#' + bc[1] : 'none'}" stroke-width="0.5"/>`;
            const tb = first(tc, /<a:txBody>[\s\S]*?<\/a:txBody>/) || '';
            const m = (k, d) => (attr(tcPr, k) != null ? pt(attr(tcPr, k)) : d);
            const body = `<a:bodyPr lIns="${m('marL', 7.2) * EMU}" rIns="${m('marR', 7.2) * EMU}" tIns="${m('marT', 3.6) * EMU}" bIns="${m('marB', 3.6) * EMU}" anchor="${attr(tcPr, 'anchor') || 't'}"/>`;
            out += textHtml(tb.replace(/<a:bodyPr[^>]*\/>|<a:bodyPr[^>]*>/, body), { x, y, w, h });
            x += w;
          });
          y += h;
        });
      }
    }
    svgs.push(out);
  }
  const markers = [...(svgs.markers || [])].map((c) => `<marker id="m${c.slice(1)}" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="5" markerHeight="5" orient="auto-start-reverse"><path d="M0,0 L10,5 L0,10 z" fill="${c}"/></marker>`).join('');
  const font = (file, w) => fs.existsSync(path.join(FONTS, file)) ? `@font-face{font-family:Poppins;font-weight:${w};src:url("${'file:///' + path.join(FONTS, file).replace(/\\/g, '/')}")}` : '';
  const html = `<!doctype html><html><head><meta charset="utf-8"><style>
${font('Poppins-Regular.ttf', 400)}${font('Poppins-SemiBold.ttf', 600)}
@font-face{font-family:Poppins;font-weight:300;src:local("Poppins Light"),local("Poppins-Light"),url("file:///${path.join(FONTS, 'Poppins-Regular.ttf').replace(/\\/g, '/')}")}
@font-face{font-family:Poppins;font-weight:500;src:local("Poppins Medium"),local("Poppins-Medium"),url("file:///${path.join(FONTS, 'Poppins-SemiBold.ttf').replace(/\\/g, '/')}")}
@page{size:${SW}pt ${SH}pt;margin:0}html,body{margin:0;padding:0}.s{width:${SW}pt;height:${SH}pt;page-break-after:always;overflow:hidden}.s svg{display:block;width:100%;height:100%}
</style></head><body>${svgs.map((s) => `<div class="s"><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${SW} ${SH}"><defs>${markers}<filter id="sh" x="-10%" y="-10%" width="130%" height="130%"><feDropShadow dx="1.5" dy="1.5" stdDeviation="2" flood-opacity="0.25"/></filter></defs>${s}</svg></div>`).join('')}</body></html>`;
  const htmlFile = opt('--html') || path.join(os.tmpdir(), `deck-${process.pid}.html`);
  fs.writeFileSync(htmlFile, html);
  const cands = [process.env.CHROME_PATH, 'C:/Program Files/Google/Chrome/Application/chrome.exe', 'C:/Program Files (x86)/Google/Chrome/Application/chrome.exe', 'C:/Program Files (x86)/Microsoft/Edge/Application/msedge.exe', 'C:/Program Files/Microsoft/Edge/Application/msedge.exe', '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome', '/usr/bin/google-chrome', '/usr/bin/chromium'].filter(Boolean);
  const chrome = cands.find((c) => fs.existsSync(c));
  if (!chrome) { console.error(`No Chrome/Edge found. The HTML is at ${htmlFile}: open it and print to PDF.`); process.exit(1); }
  const url = 'file:///' + path.resolve(htmlFile).replace(/\\/g, '/');
  const prof = fs.mkdtempSync(path.join(os.tmpdir(), 'pdfprof-'));
  const r = spawnSync(chrome, ['--headless=new', '--disable-gpu', '--no-sandbox', `--user-data-dir=${prof}`, '--allow-file-access-from-files', '--no-pdf-header-footer', '--virtual-time-budget=4000', `--print-to-pdf=${path.resolve(outPdf)}`, url], { encoding: 'utf8', timeout: 120000 });
  if (!fs.existsSync(outPdf)) { console.error('PDF not produced:', r.stderr || r.error); process.exit(1); }
  console.log(`PDF: ${path.resolve(outPdf)} (${svgs.length} slides, ${fs.statSync(outPdf).size} bytes)`);
  const pngDir = opt('--png');
  if (pngDir) {
    fs.mkdirSync(pngDir, { recursive: true });
    svgs.forEach((s, i) => {
      const one = html.replace(/<body>[\s\S]*<\/body>/, `<body><div class="s"><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${SW} ${SH}"><defs>${markers}<filter id="sh"><feDropShadow dx="1.5" dy="1.5" stdDeviation="2" flood-opacity="0.25"/></filter></defs>${s}</svg></div></body>`).replace(/\.s\{width:[^}]*\}/, `.s{width:1280px;height:${Math.round(1280 * SH / SW)}px}`);
      const f = path.join(os.tmpdir(), `slide-${process.pid}-${i + 1}.html`); fs.writeFileSync(f, one);
      spawnSync(chrome, ['--headless=new', '--disable-gpu', '--no-sandbox', `--user-data-dir=${prof}`, '--hide-scrollbars', `--window-size=1280,${Math.round(1280 * SH / SW)}`, '--virtual-time-budget=3000', `--screenshot=${path.resolve(pngDir, `slide-${String(i + 1).padStart(2, '0')}.png`)}`, 'file:///' + f.replace(/\\/g, '/')], { timeout: 60000 });
    });
    console.log(`PNG: ${path.resolve(pngDir)}`);
  }
}
main().catch((e) => { console.error(e); process.exit(1); });
